// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login 帳號密碼登入，成功時設定 HttpOnly Cookie
	// (POST /workbench/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout 登出並刪除工作階段
	// (POST /workbench/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe 目前登入者
	// (GET /workbench/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetProduct 以條碼查產品（UPC-A 與 EAN-13 視為同一條碼）
	// (GET /workbench/v1/coldstart/products/{barcode})
	GetProduct(w http.ResponseWriter, r *http.Request, barcode string)
	// ListSubmissions 列出冷啟動上傳（新的在前）
	// (GET /workbench/v1/coldstart/submissions)
	ListSubmissions(w http.ResponseWriter, r *http.Request, params ListSubmissionsParams)
	// CreateSubmission 建立一筆上傳（草稿）
	// (POST /workbench/v1/coldstart/submissions)
	CreateSubmission(w http.ResponseWriter, r *http.Request)
	// GetSubmission 取得上傳內容與前處理結果
	// (GET /workbench/v1/coldstart/submissions/{submission_id})
	GetSubmission(w http.ResponseWriter, r *http.Request, submissionId SubmissionId)
	// ConfirmSubmission 確認並寫入產品資料庫
	// (POST /workbench/v1/coldstart/submissions/{submission_id}/confirm)
	ConfirmSubmission(w http.ResponseWriter, r *http.Request, submissionId SubmissionId, params ConfirmSubmissionParams)
	// SaveDraft 儲存人工輸入（草稿可缺欄位）
	// (PUT /workbench/v1/coldstart/submissions/{submission_id}/draft)
	SaveDraft(w http.ResponseWriter, r *http.Request, submissionId SubmissionId, params SaveDraftParams)
	// GetSubmissionImage 取得上傳的原圖
	// (GET /workbench/v1/coldstart/submissions/{submission_id}/images/{kind})
	GetSubmissionImage(w http.ResponseWriter, r *http.Request, submissionId SubmissionId, kind ImageKind)
	// UploadSubmissionImage 上傳照片（重傳同一種會取代）
	// (PUT /workbench/v1/coldstart/submissions/{submission_id}/images/{kind})
	UploadSubmissionImage(w http.ResponseWriter, r *http.Request, submissionId SubmissionId, kind ImageKind)
	// RejectSubmission 退回（不建立產品）
	// (POST /workbench/v1/coldstart/submissions/{submission_id}/reject)
	RejectSubmission(w http.ResponseWriter, r *http.Request, submissionId SubmissionId, params RejectSubmissionParams)
	// GetArtifact 取得暫存影像或診斷影像
	// (GET /workbench/v1/dev/artifacts/{artifact_id})
	GetArtifact(w http.ResponseWriter, r *http.Request, artifactId string)
	// DecodeBarcode 條碼逐步升級
	// (POST /workbench/v1/dev/barcode)
	DecodeBarcode(w http.ResponseWriter, r *http.Request)
	// RunBatch 資料夾批次（以 SSE 逐張回報）
	// (POST /workbench/v1/dev/batches)
	RunBatch(w http.ResponseWriter, r *http.Request)
	// GetConfigSchemas 參數表單結構（由 Python 的 param() 宣告產生）
	// (GET /workbench/v1/dev/config-schemas)
	GetConfigSchemas(w http.ResponseWriter, r *http.Request)
	// ListE1Runs 列出 E1 執行結果
	// (GET /workbench/v1/dev/e1/runs)
	ListE1Runs(w http.ResponseWriter, r *http.Request, params ListE1RunsParams)
	// StartE1Run E1 快速執行（以 SSE 回報進度，最後一個事件為結果）
	// (POST /workbench/v1/dev/e1/runs)
	StartE1Run(w http.ResponseWriter, r *http.Request)
	// GetE1Run 取得一次 E1 執行的結果
	// (GET /workbench/v1/dev/e1/runs/{run_id})
	GetE1Run(w http.ResponseWriter, r *http.Request, runId string, params GetE1RunParams)
	// PreprocessFood 食物照片前處理（VLM 輸入、切菜、盤緣）
	// (POST /workbench/v1/dev/food)
	PreprocessFood(w http.ResponseWriter, r *http.Request)
	// PutImage 上傳並暫存影像
	// (POST /workbench/v1/dev/images)
	PutImage(w http.ResponseWriter, r *http.Request)
	// SynthesizeImage 產生合成影像並暫存（附真值）
	// (POST /workbench/v1/dev/images/synthesize)
	SynthesizeImage(w http.ResponseWriter, r *http.Request)
	// DegradeImage 套用模擬退化，產生新的暫存影像
	// (POST /workbench/v1/dev/images/{image_id}/degrade)
	DegradeImage(w http.ResponseWriter, r *http.Request, imageId ImageId)
	// LocateInvoiceQr 電子發票雙 QR 定位
	// (POST /workbench/v1/dev/invoice-qr)
	LocateInvoiceQr(w http.ResponseWriter, r *http.Request)
	// PreprocessLabel 營養標示前處理（定位、校正、光斑、對比）
	// (POST /workbench/v1/dev/label)
	PreprocessLabel(w http.ResponseWriter, r *http.Request)
	// CheckQuality 品質檢查（模糊、曝光、解析度）
	// (POST /workbench/v1/dev/quality)
	CheckQuality(w http.ResponseWriter, r *http.Request)
	// RunSweep 參數掃描
	// (POST /workbench/v1/dev/sweeps)
	RunSweep(w http.ResponseWriter, r *http.Request)
	// RenderView 產生診斷影像或圖表資料
	// (POST /workbench/v1/dev/views)
	RenderView(w http.ResponseWriter, r *http.Request)
}

